mapper.update:
UPDATE users
profile_image = #{profileImage}, phone = #{phone}, zonecode = #{zonecode}, road_address = #{roadAddress}, detail_address = #{detailAddress}, modified_at = #{modifiedAt}, modified_by = #{modifiedBy},
WHERE user_id = #{userId}

mapper.select:
SELECT i.product_id, i.title, i.content, i.is_secret, i.is_answered, i.created_at, i.created_by, u.username FROM inquiry i LEFT JOIN users u ON u.user_id = i.user_id WHERE i.user_id = #{userId}
AND product_id = #{productId}
AND i.created_at >= #{startDate}
/* 종료일 당일의 전체 데이터를 포함하기 위해 1일을 더한 미만 조건 사용 */ AND i.created_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
ORDER BY created_at DESC
